-- 4) İSG-KATİP sözleşmeleri

-- 5) ziyaret programları (canlıda olmayan firmalar)

-- 6) eksik migration kayıtları (sütunlar canlıda zaten var)

SET FOREIGN_KEY_CHECKS=1;

-- DOĞRULAMA (beklenen: kopuk_baglar = 0 ya da çok az; katip = 32):
SELECT (SELECT COUNT(*) FROM `risk_maddeleri` WHERE `tehlike_id` IS NOT NULL AND `tehlike_id` NOT IN (SELECT `id` FROM `tehlikeler`)) AS kopuk_baglar, (SELECT COUNT(*) FROM `isg_katip_sozlesmeleri`) AS katip, (SELECT COUNT(*) FROM `tehlikeler`) AS tehlikeler, (SELECT COUNT(*) FROM `tehlike_kategorileri`) AS kategoriler;
